import type { ChunkRow } from "../../../../src/store/types";

/** Compact deterministic recipe; manifest pins the complete generated bytes. */
export function hydrationLongDocument(): {
  chunks: ChunkRow[];
  content: string;
} {
  const chunks = Array.from(
    { length: 1000 },
    (_, seq): ChunkRow => ({
      mirrorHash: "hydration-long-doc-v1",
      seq,
      pos: seq * 2048,
      text: `${seq === 777 ? "needle evidence" : "background"} ${seq}\r\n${"résumé evidence ".repeat(128)}`,
      startLine: seq * 2 + 1,
      endLine: seq * 2 + 2,
      language: "markdown",
      tokenCount: 512,
      createdAt: "2026-09-05T00:00:00.000Z",
    })
  );
  return { chunks, content: chunks.map((chunk) => chunk.text).join("\n") };
}
